"""반입 꾸러미 해시 매니페스트 — 밖에서 make, 안에서 verify

  python manifest.py make bundle > bundle/MANIFEST.json
  python manifest.py verify bundle bundle/MANIFEST.json
"""
import hashlib
import json
import sys
from datetime import date
from pathlib import Path


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):   # 1MB 씩 읽어 대용량 파일도 처리
            h.update(block)
    return h.hexdigest()


def make(root: str):
    base = Path(root)
    files = {}
    for p in sorted(base.rglob("*")):
        if p.is_file() and p.name != "MANIFEST.json" and ".cache" not in p.parts:
            files[str(p.relative_to(base))] = {"sha256": sha256(p), "bytes": p.stat().st_size}
    licenses = [k for k in files if Path(k).name.upper().startswith("LICENSE")]
    manifest = {
        "created": date.today().isoformat(),
        "file_count": len(files),
        "total_gb": round(sum(v["bytes"] for v in files.values()) / 1e9, 2),
        "license_files": licenses,          # 심의 자료에 라이선스 원문을 첨부합니다
        "files": files,
    }
    print(json.dumps(manifest, ensure_ascii=False, indent=1))
    if not licenses:
        print("경고: LICENSE 파일이 없습니다. 모델 카드에서 라이선스를 확인하세요.", file=sys.stderr)


def verify(root: str, manifest_path: str) -> int:
    base = Path(root)
    manifest = json.load(open(manifest_path, encoding="utf-8"))
    bad = 0
    for rel, meta in manifest["files"].items():
        p = base / rel
        if not p.exists():
            print("없음  ", rel)
            bad += 1
        elif sha256(p) != meta["sha256"]:
            print("불일치", rel)
            bad += 1
    print(f"검증 {manifest['file_count']}개 중 문제 {bad}개")
    return 1 if bad else 0


if __name__ == "__main__":
    cmd, *args = sys.argv[1:]
    sys.exit(make(*args) if cmd == "make" else verify(*args))

package study.s21;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;

/**
 * GPU 메모리 추정기 — 추정값입니다. 실제 사용량은 엔진·설정에 따라 다릅니다. (Python 트랙 estimate_vram.py 와 같은 식)
 *
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s21.VramEstimator \
 *     -Dexec.args="--params 8 --bits 16 --ctx 8192 --concurrency 8 --gpu-gb 48"
 *   ... -Dexec.args="--config ./models/Qwen3.5-9B/config.json --params 9 --bits 4 --ctx 16384 --concurrency 4"
 */
public final class VramEstimator {

    record Arch(int layers, int kvHeads, int headDim) {}

    record Estimate(double weightsGb, long kvPerToken, double kvGb, double totalGb) {}

    /** Hugging Face config.json 에서 층 수 · KV 헤드 · 헤드 차원을 읽습니다. 멀티모달 모델은 text_config 아래에 있습니다. */
    static Arch fromConfig(Path path) throws IOException {
        JsonNode cfg = new ObjectMapper().readTree(path.toFile());
        if (cfg.has("text_config")) cfg = cfg.get("text_config");
        int layers = cfg.get("num_hidden_layers").asInt();
        int heads = cfg.get("num_attention_heads").asInt();
        int kvHeads = cfg.path("num_key_value_heads").asInt(heads);
        int headDim = cfg.hasNonNull("head_dim") ? cfg.get("head_dim").asInt() : cfg.get("hidden_size").asInt() / heads;
        return new Arch(layers, kvHeads, headDim);
    }

    static Estimate estimate(double paramsB, double bits, Arch a, int ctx, int concurrency, int kvBytes, double overhead) {
        double weightsGb = paramsB * 1e9 * bits / 8 / 1e9;
        // K 와 V 두 벌 × 층 × KV 헤드 × 헤드 차원 × 바이트 = 토큰 하나당 KV 캐시
        long kvPerToken = 2L * a.layers() * a.kvHeads() * a.headDim() * kvBytes;
        double kvGb = (double) kvPerToken * ctx * concurrency / 1e9;
        return new Estimate(weightsGb, kvPerToken, kvGb, (weightsGb + kvGb) * (1 + overhead));
    }

    public static void main(String[] args) throws IOException {
        Map<String, String> o = new HashMap<>(Map.of("--bits", "16", "--layers", "32", "--kv-heads", "8", "--head-dim", "128",
                "--ctx", "8192", "--concurrency", "4", "--kv-bytes", "2", "--gpu-gb", "48"));
        for (int i = 0; i + 1 < args.length; i += 2) o.put(args[i], args[i + 1]);
        if (!o.containsKey("--params")) {
            System.err.println("--params(십억, B)는 필수입니다. 예: --params 8");
            System.exit(2);
        }
        Arch arch = o.containsKey("--config") ? fromConfig(Path.of(o.get("--config")))
                : new Arch(Integer.parseInt(o.get("--layers")), Integer.parseInt(o.get("--kv-heads")), Integer.parseInt(o.get("--head-dim")));
        double params = Double.parseDouble(o.get("--params"));
        double bits = Double.parseDouble(o.get("--bits"));
        int ctx = Integer.parseInt(o.get("--ctx"));
        int conc = Integer.parseInt(o.get("--concurrency"));
        Estimate e = estimate(params, bits, arch, ctx, conc, Integer.parseInt(o.get("--kv-bytes")), 0.15);

        System.out.printf("구조: 층 %d · KV 헤드 %d · 헤드 차원 %d%n", arch.layers(), arch.kvHeads(), arch.headDim());
        System.out.printf("가중치        %6.1f GB  (%sB × %sbit)%n", e.weightsGb(), o.get("--params"), o.get("--bits"));
        System.out.printf("KV 캐시/토큰  %6.1f KiB%n", e.kvPerToken() / 1024.0);
        System.out.printf("KV 캐시 합계  %6.1f GB  (%d 토큰 × 동시 %d)%n", e.kvGb(), ctx, conc);
        System.out.printf("여유분 포함   %6.1f GB  (추정)%n", e.totalGb());
        double gpu = Double.parseDouble(o.get("--gpu-gb"));
        double budget = gpu * 0.9;
        System.out.printf("GPU %.0fGB × 0.9 = %.1f GB → %s%n", gpu, budget,
                e.totalGb() <= budget ? "들어감" : "부족 — 비트·컨텍스트·동시 요청을 줄이거나 GPU 추가");
    }
}

package study.s21;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.function.Consumer;

/**
 * 사내 vLLM · Ollama · llama.cpp 의 OpenAI 호환 /v1/chat/completions 를 JDK HttpClient + Jackson 으로 부릅니다.
 * LLM_BASE_URL, LLM_API_KEY, LLM_MODEL 만 바꾸면 같은 코드로 대상을 바꿉니다. (외부 SDK 없이 폐쇄망 반입이 쉬움)
 *
 *   ./mvnw -q compile exec:java -Dexec.args="야간 배치 재처리 절차를 요약해 주세요"
 *   LLM_STREAM=0 ./mvnw -q compile exec:java      # 스트리밍 없이 한 번에
 */
public final class LlmClient {

    public static final String BASE_URL = env("LLM_BASE_URL", "http://localhost:8000/v1");
    public static final String API_KEY = env("LLM_API_KEY", "change-me");
    public static final String MODEL = env("LLM_MODEL", "qwen3.5-9b");   // vllm serve --served-model-name 과 같게

    static final ObjectMapper JSON = new ObjectMapper();
    static final String SYSTEM = "당신은 증권사 정보계 운영 문서를 요약하는 도우미입니다. 한국어로, 5줄 이내로 답합니다.";

    private final HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();

    /** 요청 본문. 로컬 오픈웨이트 모델이므로 temperature 를 직접 정합니다 (Claude 5.5 와 달리 허용). */
    static ObjectNode body(String model, String system, String user, int maxTokens, double temperature, boolean stream) {
        ObjectNode b = JSON.createObjectNode();
        b.put("model", model);
        b.put("max_tokens", maxTokens);
        b.put("temperature", temperature);
        b.put("stream", stream);
        ArrayNode msgs = b.putArray("messages");
        if (system != null) msgs.addObject().put("role", "system").put("content", system);
        msgs.addObject().put("role", "user").put("content", user);
        return b;
    }

    HttpRequest request(ObjectNode body) {
        return HttpRequest.newBuilder(URI.create(BASE_URL + "/chat/completions"))
                .timeout(Duration.ofSeconds(120))
                .header("Content-Type", "application/json")
                .header("Authorization", "Bearer " + API_KEY)
                .POST(HttpRequest.BodyPublishers.ofString(body.toString(), StandardCharsets.UTF_8))
                .build();
    }

    /** 한 번에 받기 */
    public String ask(String question) throws IOException, InterruptedException {
        HttpResponse<String> res = http.send(request(body(MODEL, SYSTEM, question, 600, 0.2, false)),
                HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
        if (res.statusCode() != 200) throw new IOException("HTTP " + res.statusCode() + ": " + res.body());
        return JSON.readTree(res.body()).at("/choices/0/message/content").asText();
    }

    /**
     * 스트리밍(SSE): 'data: {json}' 줄마다 choices[0].delta.content 조각을 onToken 으로 넘깁니다. 'data: [DONE]' 에서 끝.
     * 돌려주는 값은 받은 조각 수 (출력 토큰 수의 근사치).
     */
    public int stream(ObjectNode body, Consumer<String> onToken) throws IOException, InterruptedException {
        HttpResponse<InputStream> res = http.send(request(body), HttpResponse.BodyHandlers.ofInputStream());
        if (res.statusCode() != 200) {
            try (InputStream in = res.body()) {
                throw new IOException("HTTP " + res.statusCode() + ": " + new String(in.readAllBytes(), StandardCharsets.UTF_8));
            }
        }
        int chunks = 0;
        try (BufferedReader r = new BufferedReader(new InputStreamReader(res.body(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) {
                if (!line.startsWith("data:")) continue;          // 빈 줄 · 주석 줄 건너뜀
                String data = line.substring(5).strip();
                if (data.equals("[DONE]")) break;
                JsonNode delta = JSON.readTree(data).at("/choices/0/delta/content");
                if (delta.isTextual() && !delta.asText().isEmpty()) {
                    chunks++;
                    onToken.accept(delta.asText());
                }
            }
        }
        return chunks;
    }

    static String env(String k, String def) {
        return System.getenv().getOrDefault(k, def);
    }

    public static void main(String[] args) throws Exception {
        String q = args.length > 0 ? String.join(" ", args) : "야간 배치 재처리 절차를 신규 담당자에게 설명하듯 요약해 주세요.";
        LlmClient c = new LlmClient();
        System.out.println("[" + BASE_URL + " · " + MODEL + "]");
        if ("0".equals(env("LLM_STREAM", "1"))) {
            System.out.println(c.ask(q));
        } else {
            c.stream(body(MODEL, SYSTEM, q, 600, 0.2, true), t -> {
                System.out.print(t);
                System.out.flush();
            });
            System.out.println();
        }
    }
}

package study.s21;

import com.fasterxml.jackson.databind.node.ObjectNode;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.Semaphore;

/**
 * 간단 처리량·지연 벤치마크 — 동시 요청 수를 바꿔 TTFT(첫 토큰까지 시간)와 출력 처리량을 잽니다.
 *
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s21.Bench -Dexec.args="--concurrency 4 --requests 20"
 *
 * 요청마다 가상 스레드 하나, 동시 실행 수는 Semaphore 로 제한합니다. 조각 수를 출력 토큰의 근사값으로 씁니다.
 * 정밀 측정은 vLLM 의 vllm bench serve 를 씁니다.
 */
public final class Bench {

    record Sample(double ttft, double total, int chunks) {}

    static final String PROMPT = "다음 장애 보고를 3줄로 요약하세요.\n"
            + "02:10 원장 일배치 지연. 원천 파일 수신이 40분 늦어 STG 적재가 대기했고, "
            + "03:05 수신 확인 후 재처리하여 04:20 정상 종료. 영향: 아침 보고서 20분 지연.";

    public static void main(String[] args) throws Exception {
        Map<String, String> o = new HashMap<>(Map.of("--concurrency", "4", "--requests", "20"));
        for (int i = 0; i + 1 < args.length; i += 2) o.put(args[i], args[i + 1]);
        int concurrency = Integer.parseInt(o.get("--concurrency"));
        int requests = Integer.parseInt(o.get("--requests"));

        LlmClient client = new LlmClient();
        Semaphore sem = new Semaphore(concurrency);
        long t0 = System.nanoTime();
        List<Future<Sample>> futures = new ArrayList<>();
        try (ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < requests; i++) {
                futures.add(pool.submit(() -> {
                    sem.acquire();
                    try {
                        long start = System.nanoTime();
                        long[] first = {0};
                        ObjectNode body = LlmClient.body(LlmClient.MODEL, null, PROMPT, 256, 0, true);
                        int chunks = client.stream(body, t -> {
                            if (first[0] == 0) first[0] = System.nanoTime();
                        });
                        double ttft = first[0] == 0 ? 0 : (first[0] - start) / 1e9;
                        return new Sample(ttft, (System.nanoTime() - start) / 1e9, chunks);
                    } finally {
                        sem.release();
                    }
                }));
            }
        }   // close() 가 모든 요청이 끝날 때까지 기다립니다
        double wall = (System.nanoTime() - t0) / 1e9;

        List<Double> ttft = new ArrayList<>();
        double sumTotal = 0;
        long tokens = 0;
        for (Future<Sample> f : futures) {
            Sample s = f.get();
            ttft.add(s.ttft());
            sumTotal += s.total();
            tokens += s.chunks();
        }
        Collections.sort(ttft);
        int n = ttft.size();
        double median = n % 2 == 1 ? ttft.get(n / 2) : (ttft.get(n / 2 - 1) + ttft.get(n / 2)) / 2;
        double p95 = ttft.size() > 1 ? ttft.get((int) (ttft.size() * 0.95) - 1) : ttft.get(0);   // Python 트랙과 같은 계산
        System.out.printf("동시 %d · 요청 %d건 · 총 %.1f초%n", concurrency, requests, wall);
        System.out.printf("TTFT 중앙값 %.2fs · p95 %.2fs%n", median, p95);
        System.out.printf("요청당 평균 %.2fs%n", sumTotal / requests);
        System.out.printf("출력 처리량 약 %.0f 토큰/초 (조각 기준 근사)%n", tokens / wall);
    }
}

package study.s21;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * 최소 LLM 게이트웨이 — 사내 클라이언트는 이 주소 하나만 알고, 뒤의 vLLM·Ollama 는 바꿔 끼웁니다.
 *  - 10초마다 각 백엔드의 GET /v1/models 로 상태 확인, 요청은 살아 있는 첫 백엔드로 전달 (순서 = 우선순위)
 *  - 클라이언트 키 검사(GATEWAY_KEY), 감사 로그는 본문 대신 길이·해시만 남김
 *  - 스트리밍 응답은 그대로 흘려보냄
 *
 *   export LLM_BACKENDS="vllm=http://gpu01:8000/v1|change-me,ollama=http://localhost:11434/v1|ollama"
 *   export GATEWAY_KEY=team-key
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s21.MiniGateway      # http://0.0.0.0:9000/v1
 *
 * 학습용 최소 구현입니다. 운영에서는 사내 표준 API 게이트웨이(인증·속도 제한·로그 수집)를 앞에 둡니다.
 */
public final class MiniGateway {

    record Backend(String name, String baseUrl, String apiKey) {}

    static final HttpClient HTTP = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
    static final Map<String, Boolean> HEALTHY = new ConcurrentHashMap<>();

    public static void main(String[] args) throws IOException {
        List<Backend> backends = parse(System.getenv().getOrDefault("LLM_BACKENDS",
                "vllm=http://localhost:8000/v1|change-me,ollama=http://localhost:11434/v1|ollama"));
        String gatewayKey = System.getenv().getOrDefault("GATEWAY_KEY", "");
        int port = Integer.parseInt(System.getenv().getOrDefault("GATEWAY_PORT", "9000"));

        ScheduledExecutorService health = Executors.newSingleThreadScheduledExecutor();
        health.scheduleAtFixedRate(() -> backends.forEach(b -> {
            boolean ok = isHealthy(b);
            Boolean before = HEALTHY.put(b.name(), ok);
            if (before == null || before != ok) System.err.printf("%s [health] %s → %s%n", LocalDateTime.now(), b.name(), ok ? "UP" : "DOWN");
        }), 0, 10, TimeUnit.SECONDS);

        HttpServer server = HttpServer.create(new InetSocketAddress(port), 0);
        server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        server.createContext("/healthz", ex -> reply(ex, 200, HEALTHY.toString()));
        server.createContext("/v1/", ex -> {
            if (!gatewayKey.isEmpty() && !("Bearer " + gatewayKey).equals(ex.getRequestHeaders().getFirst("Authorization"))) {
                reply(ex, 401, "{\"error\":\"unauthorized\"}");
                return;
            }
            Backend b = backends.stream().filter(x -> HEALTHY.getOrDefault(x.name(), false)).findFirst().orElse(null);
            if (b == null) {
                reply(ex, 503, "{\"error\":\"no healthy backend\"}");
                return;
            }
            forward(ex, b);
        });
        server.start();
        System.out.println("게이트웨이 http://0.0.0.0:" + port + "/v1 → "
                + backends.stream().map(b -> b.name() + "=" + b.baseUrl()).toList());   // 키는 출력하지 않음
    }

    static void forward(HttpExchange ex, Backend b) throws IOException {
        byte[] body = ex.getRequestBody().readAllBytes();
        String path = ex.getRequestURI().getPath().substring("/v1".length());   // /chat/completions 등
        long t0 = System.nanoTime();
        HttpRequest.Builder req = HttpRequest.newBuilder(URI.create(b.baseUrl() + path))
                .timeout(Duration.ofSeconds(300))
                .header("Content-Type", "application/json")
                .header("Authorization", "Bearer " + b.apiKey());
        req = "GET".equals(ex.getRequestMethod()) ? req.GET() : req.POST(HttpRequest.BodyPublishers.ofByteArray(body));
        try {
            HttpResponse<InputStream> res = HTTP.send(req.build(), HttpResponse.BodyHandlers.ofInputStream());
            res.headers().firstValue("Content-Type").ifPresent(ct -> ex.getResponseHeaders().set("Content-Type", ct));
            ex.sendResponseHeaders(res.statusCode(), 0);           // 0 = 길이 미정(청크 전송) → 스트리밍 통과
            try (InputStream in = res.body(); OutputStream out = ex.getResponseBody()) {
                in.transferTo(out);
            }
            // 감사 로그: 프롬프트 원문 대신 길이와 해시만 (원문 보관은 사내 정책에 따름)
            System.out.printf("%s %s %s → %s %d %dms req=%dB sha256=%s%n", LocalDateTime.now(), ex.getRemoteAddress().getAddress().getHostAddress(),
                    path, b.name(), res.statusCode(), (System.nanoTime() - t0) / 1_000_000, body.length, sha256(body).substring(0, 16));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            reply(ex, 502, "{\"error\":\"interrupted\"}");
        } catch (IOException e) {
            HEALTHY.put(b.name(), false);                          // 다음 요청부터 다른 백엔드로
            reply(ex, 502, "{\"error\":\"backend " + b.name() + " failed\"}");
        }
    }

    static boolean isHealthy(Backend b) {
        try {
            HttpRequest r = HttpRequest.newBuilder(URI.create(b.baseUrl() + "/models"))
                    .timeout(Duration.ofSeconds(3)).header("Authorization", "Bearer " + b.apiKey()).GET().build();
            return HTTP.send(r, HttpResponse.BodyHandlers.discarding()).statusCode() == 200;
        } catch (Exception e) {
            return false;
        }
    }

    /** "이름=주소|키,이름=주소|키" 형식 */
    static List<Backend> parse(String spec) {
        List<Backend> out = new ArrayList<>();
        for (String item : spec.split(",")) {
            String[] nameRest = item.strip().split("=", 2);
            String[] urlKey = nameRest[1].split("\\|", 2);
            out.add(new Backend(nameRest[0], urlKey[0], urlKey.length > 1 ? urlKey[1] : "none"));
        }
        return out;
    }

    static void reply(HttpExchange ex, int status, String text) throws IOException {
        byte[] b = text.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
        ex.sendResponseHeaders(status, b.length);
        try (OutputStream out = ex.getResponseBody()) {
            out.write(b);
        }
    }

    static String sha256(byte[] data) {
        try {
            StringBuilder sb = new StringBuilder();
            for (byte x : MessageDigest.getInstance("SHA-256").digest(data)) sb.append(String.format("%02x", x));
            return sb.toString();
        } catch (Exception e) {
            return "-";
        }
    }
